CREATE TABLE research_requests (request_id text NOT NULL, version text NOT NULL, account_domain text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(request_id,version));
CREATE TABLE research_sources (request_id text NOT NULL, request_version text NOT NULL, source_id text NOT NULL, url text NOT NULL, source_type text NOT NULL, published_at timestamptz NOT NULL, content_fingerprint text NOT NULL, synthetic boolean NOT NULL DEFAULT true, PRIMARY KEY(request_id,request_version,source_id));
CREATE TABLE research_claims (request_id text NOT NULL, request_version text NOT NULL, claim_id text NOT NULL, statement text NOT NULL, status text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), source_ids jsonb NOT NULL, PRIMARY KEY(request_id,request_version,claim_id));
CREATE TABLE agent_traces (trace_id bigserial PRIMARY KEY, request_id text NOT NULL, step_id text NOT NULL, agent text NOT NULL, tool text NOT NULL, status text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_briefs (brief_fingerprint text PRIMARY KEY, request_id text NOT NULL, request_version text NOT NULL, status text NOT NULL, payload jsonb NOT NULL, evidence_boundary text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE human_reviews (audit_fingerprint text PRIMARY KEY, brief_fingerprint text NOT NULL REFERENCES research_briefs(brief_fingerprint), reviewer_id text NOT NULL, reviewer_role text NOT NULL, decision text NOT NULL, rationale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_dlq (job_id text PRIMARY KEY, attempts integer NOT NULL, reason text NOT NULL, auto_replay boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
